"use client";
import { Music2, VolumeX } from "lucide-react";
import { useRef, useState } from "react";
export function MusicControl() { const [on,setOn]=useState(false); const audio=useRef<AudioContext|null>(null); const timer=useRef<number|undefined>(undefined); const toggle=()=>{ if(on){window.clearTimeout(timer.current);audio.current?.close();audio.current=null;setOn(false);return;} const ctx=new AudioContext();audio.current=ctx; const melody=[[392,.28],[392,.28],[440,.55],[392,.55],[523,.55],[494,1],[392,.28],[392,.28],[440,.55],[392,.55],[587,.55],[523,1],[392,.28],[392,.28],[784,.55],[659,.55],[523,.55],[494,.55],[440,.8],[698,.28],[698,.28],[659,.55],[523,.55],[587,.55],[523,1.1]] as const; const play=()=>{let at=ctx.currentTime+.05; melody.forEach(([frequency,duration])=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type="triangle";o.frequency.value=frequency;g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(.075,at+.025);g.gain.exponentialRampToValueAtTime(.0001,at+duration*.92);o.connect(g).connect(ctx.destination);o.start(at);o.stop(at+duration);at+=duration});timer.current=window.setTimeout(play,(at-ctx.currentTime+.8)*1000)};play();setOn(true)}; return <button className="music" onClick={toggle} aria-label={on ? "Couper la musique" : "Jouer Joyeux anniversaire"}>{on ? <Music2 size={18}/>:<VolumeX size={18}/>}<span>{on ? "Joyeux anniversaire" : "Musique"}</span></button> }
