"use client";
import { motion } from "framer-motion";

export function Cake({ blown }: { blown: boolean }) {
  return <motion.div className="cake-wrap" animate={{ y: [0, -8, 0] }} transition={{ duration: 3.5, repeat: Infinity, ease: "easeInOut" }} aria-label="Gâteau d'anniversaire avec cinq bougies">
    <div className="candles">{[0,1,2,3,4].map((c) => <div className="candle" key={c}><motion.i className="flame" animate={blown ? { scale: 0, opacity: 0 } : { scale: [1, .78, 1], rotate: [-4, 4, -4] }} transition={{ duration: blown ? .6 : .42, repeat: blown ? 0 : Infinity }} />{blown && <span className="smoke" />}</div>)}</div>
    <div className="cake-top" /><div className="cake-body"><span /><span /><span /></div><div className="cake-base" />
  </motion.div>;
}
